package com.tnr.cityguide.config;
import com.tnr.cityguide.favorite.*;import com.tnr.cityguide.place.*;import com.tnr.cityguide.review.*;import com.tnr.cityguide.user.*;
import java.security.SecureRandom;import java.util.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Profile;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component @Profile("local")
public class DevDataInitializer implements CommandLineRunner {
 private static final String[] NAMES={"Amara O.","Liam K.","Sofia R.","Kenji T.","Priya S.","Daniel M.","Chloé B."};
 private static final String[] EMAILS={"amara@seed.cityguide.app","liam@seed.cityguide.app","sofia@seed.cityguide.app","kenji@seed.cityguide.app","priya@seed.cityguide.app","daniel@seed.cityguide.app","chloe@seed.cityguide.app"};
 private static final String[] TEXTS={"Absolutely worth it. Go early to avoid the crowds.","Great atmosphere and friendly staff. Would visit again.","A highlight of our trip – the photos don’t do it justice.","Well organised and easy to reach by public transport.","Lovely spot. A little busy at weekends but still enjoyable.","Good value and a memorable experience overall.","Exactly what I hoped for. Highly recommended for first-timers."};
 private final UserRepository users;private final PlaceRepository places;private final ReviewRepository reviews;private final ReviewLikeRepository likes;private final FavoriteRepository favorites;private final PasswordEncoder encoder;private final SecureRandom random=new SecureRandom();
 public DevDataInitializer(UserRepository users,PlaceRepository places,ReviewRepository reviews,ReviewLikeRepository likes,FavoriteRepository favorites,PasswordEncoder encoder){this.users=users;this.places=places;this.reviews=reviews;this.likes=likes;this.favorites=favorites;this.encoder=encoder;}
 @Override @Transactional public void run(String... args){
  User demo=users.findByEmailIgnoreCase("demo@cityguide.app").orElseGet(()->{User u=new User();u.setName("Demo Traveller");u.setEmail("demo@cityguide.app");u.setPhone("+1 555 0100");u.setPasswordHash(encoder.encode("Demo@1234"));return users.save(u);});
  addFavorite(demo.getId(),"eiffel");addFavorite(demo.getId(),"centralpark");
  List<User> reviewers=new ArrayList<>();for(int i=0;i<EMAILS.length;i++){final int index=i;User u=users.findByEmailIgnoreCase(EMAILS[i]).orElseGet(()->{byte[] b=new byte[32];random.nextBytes(b);User created=new User();created.setName(NAMES[index]);created.setEmail(EMAILS[index]);created.setPasswordHash(encoder.encode(Base64.getUrlEncoder().withoutPadding().encodeToString(b)));return users.save(created);});reviewers.add(u);}
  for(Place place:places.findAll()){int rounded=(int)Math.round(place.getBaseRating()),ceiling=(int)Math.ceil(place.getBaseRating()),floor=(int)Math.floor(place.getBaseRating());int[] ratings={Math.max(1,Math.min(5,rounded)),Math.min(5,ceiling),Math.max(1,floor)};for(int j=0;j<3;j++){User author=reviewers.get(j);if(reviews.findByPlaceIdAndUserId(place.getId(),author.getId()).isEmpty()){Review review=new Review();review.setPlaceId(place.getId());review.setUserId(author.getId());review.setRating((short)ratings[j]);review.setText(TEXTS[j]);reviews.save(review);}}}
  List<Review> all=reviews.findAll();for(Review review:all){for(int j=3;j<Math.min(5,reviewers.size());j++){ReviewLike.Key key=new ReviewLike.Key(review.getId(),reviewers.get(j).getId());if(!likes.existsById(key)){ReviewLike like=new ReviewLike();like.setReviewId(review.getId());like.setUserId(reviewers.get(j).getId());likes.save(like);}}}
  for(Place place:places.findAll()){List<Review> rows=reviews.findByPlaceIdOrderByCreatedAtDesc(place.getId());place.setReviewCount(rows.size());place.setRatingAvg(rows.isEmpty()?place.getBaseRating():rows.stream().mapToInt(Review::getRating).average().orElse(place.getBaseRating()));}
 }
 private void addFavorite(UUID user,String place){if(places.existsById(place)){Favorite.Key key=new Favorite.Key(user,place);if(!favorites.existsById(key)){Favorite f=new Favorite();f.setUserId(user);f.setPlaceId(place);favorites.save(f);}}}
}
